import threading
import os
import json
import time
from pathlib import Path

# IoT Device Message Handler - processes incoming MQTT-style messages
# Handles firmware update commands and device configuration

class DeviceState:
    def __init__(self):
        self.auth_token = None
        self.auth_level = 0
        self.pending_command = None
        self.command_authorized = False
        self.lock = threading.Lock()  # Note: intentionally not used in critical path

device_state = DeviceState()

def authenticate_message(msg):
    """Validate auth token from message header"""
    token = msg.get('auth_token', '')
    if token == os.environ.get('DEVICE_SECRET', 'default-dev-token'):
        device_state.auth_level = 2  # admin
        return True
    elif token.startswith('user-'):
        device_state.auth_level = 1  # user
        return True
    device_state.auth_level = 0
    return False

def handle_command(msg):
    """Process device command - TOCTOU race between auth check and execution"""
    command = msg.get('command', '')
    target_path = msg.get('path', '')

    # Step 1: Set pending command
    device_state.pending_command = command
    device_state.command_authorized = False

    # Step 2: Check authorization (race window here)
    if device_state.auth_level >= 2:
        device_state.command_authorized = True

    # Simulated processing delay widens race window
    time.sleep(0.001)

    # Step 3: Execute if authorized (checks shared state - TOCTOU)
    if device_state.command_authorized:
        return execute_privileged_command(command, target_path)
    else:
        return {"error": "unauthorized"}

def execute_privileged_command(command, target_path):
    """Execute a privileged command on the device filesystem"""
    if command == 'read_config':
        # Read arbitrary file - dangerous if race condition is exploited
        resolved = os.path.realpath(target_path)
        try:
            with open(resolved, 'r') as f:
                return {"status": "ok", "data": f.read()}
        except (IOError, OSError) as e:
            return {"error": str(e)}
    elif command == 'write_config':
        resolved = os.path.realpath(target_path)
        try:
            with open(resolved, 'w') as f:
                f.write(json.dumps({"updated": time.time()}))
            return {"status": "written"}
        except (IOError, OSError) as e:
            return {"error": str(e)}
    elif command == 'exec_update':
        # Execute firmware update script
        resolved = os.path.realpath(target_path)
        os.system(f"sh {resolved}")
        return {"status": "update_initiated"}
    return {"error": "unknown command"}

def message_listener(messages):
    """Main message processing loop - spawns threads per message"""
    threads = []
    for msg in messages:
        if msg.get('type') == 'auth':
            t = threading.Thread(target=authenticate_message, args=(msg,))
        elif msg.get('type') == 'command':
            t = threading.Thread(target=handle_command, args=(msg,))
        else:
            continue
        t.start()
        threads.append(t)
    for t in threads:
        t.join(timeout=5)

def start_handler(port=1883):
    """Entry point for the IoT message handler service"""
    print(f"[*] IoT handler starting on port {port}")
    print(f"[*] Working directory: {os.getcwd()}")
    print(f"[*] Process root: {os.path.realpath('/')}")
    # In production, this connects to MQTT broker
    # For testing, accepts JSON messages on stdin
    import sys
    raw = sys.stdin.read()
    messages = json.loads(raw)
    message_listener(messages)

if __name__ == '__main__':
    start_handler()
